CREATE TABLE IF NOT EXISTS cms_import_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,source_type TEXT NOT NULL,source_fingerprint TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','completed','failed')),cursor_value TEXT,stats_json TEXT NOT NULL DEFAULT '{}',options_json TEXT NOT NULL DEFAULT '{}',last_error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT);
CREATE TABLE IF NOT EXISTS cms_import_mappings(job_id INTEGER NOT NULL REFERENCES cms_import_jobs(id) ON DELETE CASCADE,source_kind TEXT NOT NULL,source_id TEXT NOT NULL,target_kind TEXT NOT NULL,target_id INTEGER NOT NULL,metadata_json TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(job_id,source_kind,source_id));
CREATE TABLE IF NOT EXISTS cms_import_media(job_id INTEGER NOT NULL REFERENCES cms_import_jobs(id) ON DELETE CASCADE,source_url TEXT NOT NULL,target_media_id INTEGER,sha256 TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','imported','skipped','failed')),last_error TEXT,PRIMARY KEY(job_id,source_url));
CREATE TABLE IF NOT EXISTS cms_import_reports(id INTEGER PRIMARY KEY AUTOINCREMENT,job_id INTEGER NOT NULL REFERENCES cms_import_jobs(id) ON DELETE CASCADE,report_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
