CREATE TABLE cms_pages_10260 (id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT NOT NULL,locale TEXT NOT NULL DEFAULT 'fa',title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',is_home INTEGER NOT NULL DEFAULT 0,author_id INTEGER REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,meta_title TEXT NOT NULL DEFAULT '',meta_description TEXT NOT NULL DEFAULT '',canonical_url TEXT NOT NULL DEFAULT '',featured_image TEXT NOT NULL DEFAULT '',content_type TEXT NOT NULL DEFAULT 'page',published_at TEXT,source_provider TEXT NOT NULL DEFAULT '',source_ref TEXT NOT NULL DEFAULT '',robots_index INTEGER NOT NULL DEFAULT 1 CHECK(robots_index IN(0,1)),robots_follow INTEGER NOT NULL DEFAULT 1 CHECK(robots_follow IN(0,1)),og_title TEXT NOT NULL DEFAULT '',og_description TEXT NOT NULL DEFAULT '',schema_type TEXT NOT NULL DEFAULT 'Article',trash_status TEXT NOT NULL DEFAULT 'active' CHECK(trash_status IN('active','trash')),trashed_at TEXT,trashed_by INTEGER REFERENCES users(id) ON DELETE SET NULL,block_schema_version INTEGER NOT NULL DEFAULT 0,block_document TEXT NOT NULL DEFAULT '',editorial_state TEXT NOT NULL DEFAULT 'draft' CHECK(editorial_state IN('draft','in_review','approved','scheduled','published','rejected')),review_requested_at TEXT,reviewed_at TEXT,reviewed_by INTEGER REFERENCES users(id) ON DELETE SET NULL,UNIQUE(slug,locale));
